const express = require('express');
const serialize = require('node-serialize');
const session = require('express-session');
const crypto = require('crypto');

const app = express();

// Session configuration
app.use(session({
  secret: crypto.randomBytes(32).toString('hex'),
  resave: false,
  saveUninitialized: false,
  cookie: { secure: true, httpOnly: true, sameSite: 'strict' }
}));

app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true }));

// Middleware: request logging
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const clientIP = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  console.log(`[${timestamp}] ${req.method} ${req.path} from ${clientIP}`);
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', uptime: process.uptime() });
});

// Internal API: restore user preferences from serialized state
// Used by internal microservices to sync user settings across services
app.post('/api/v1/preferences/restore', (req, res) => {
  try {
    const { userId, serializedState } = req.body;

    if (!userId || !serializedState) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    // Validate userId format
    if (!/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(userId)) {
      return res.status(400).json({ error: 'Invalid userId format' });
    }

    // Deserialize the user preferences state
    // This is an internal-only endpoint consumed by our preference-sync service
    const userPreferences = serialize.unserialize(serializedState);

    if (!userPreferences || typeof userPreferences !== 'object') {
      return res.status(400).json({ error: 'Invalid preference state' });
    }

    // Apply preferences
    const applied = {
      userId: userId,
      theme: userPreferences.theme || 'default',
      language: userPreferences.language || 'en',
      notifications: userPreferences.notifications !== undefined ? userPreferences.notifications : true,
      dashboard_layout: userPreferences.dashboard_layout || 'grid',
      timezone: userPreferences.timezone || 'UTC',
      restoredAt: new Date().toISOString()
    };

    console.log(`Preferences restored for user ${userId}`);
    res.json({ success: true, preferences: applied });
  } catch (err) {
    console.error('Error restoring preferences:', err.message);
    res.status(500).json({ error: 'Failed to restore preferences' });
  }
});

// Internal API: batch preference sync
app.post('/api/v1/preferences/batch-sync', (req, res) => {
  try {
    const { states } = req.body;

    if (!Array.isArray(states) || states.length === 0) {
      return res.status(400).json({ error: 'States must be a non-empty array' });
    }

    if (states.length > 100) {
      return res.status(400).json({ error: 'Batch size exceeds limit of 100' });
    }

    const results = states.map((item, index) => {
      try {
        const prefs = serialize.unserialize(item.serializedState);
        return { index, userId: item.userId, status: 'restored' };
      } catch (e) {
        return { index, userId: item.userId, status: 'failed', error: e.message };
      }
    });

    res.json({ results });
  } catch (err) {
    console.error('Batch sync error:', err.message);
    res.status(500).json({ error: 'Batch sync failed' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Preference service listening on port ${PORT}`);
});
